```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

// Fonction de conversion de Markdown en HTML
std::string markdownToHtml(const std::string& markdown) {
    pugi::xml_document doc;
    pugi::xml_node root;

    // Créer le document XML à partir du Markdown
    pugi::xml_parse_result result = doc.load_string(markdown.c_str());

    if (result) {
        root = doc.first_child();

        // Appliquer les règles de conversion de Markdown en HTML
        pugi::xml_node header_node = root.child("h1");
        if (header_node) {
            header_node.prepend_child(pugi::node_type::pcdata).set_value("h1> ");
            header_node.append_child(pugi::node_type::pcdata).set_value(" </h1>");
        }

        pugi::xml_node paragraph_node = root.child("p");
        if (paragraph_node) {
            paragraph_node.prepend_child(pugi::node_type::pcdata).set_value("<p>");
            paragraph_node.append_child(pugi::node_type::pcdata).set_value("</p>");
        }

        pugi::xml_node strong_node = root.child("strong");
        if (strong_node) {
            strong_node.prepend_child(pugi::node_type::pcdata).set_value("<strong>");
            strong_node.append_child(pugi::node_type::pcdata).set_value("</strong>");
        }

        pugi::xml_node em_node = root.child("em");
        if (em_node) {
            em_node.prepend_child(pugi::node_type::pcdata).set_value("<em>");
            em_node.append_child(pugi::node_type::pcdata).set_value("</em>");
        }

        pugi::xml_node img_node = root.child("img");
        if (img_node) {
            img_node.prepend_child(pugi::node_type::pcdata).set_value("<img src=\"");
            img_node.append_child(pugi::node_type::pcdata).set_value("\" alt=\"");
            img_node.append_child(pugi::node_type::pcdata).set_value("\" />");
        }

        // Convertir le document XML en chaîne de caractères HTML
        std::string html;
        pugi::print_node(html, root);
        return html;
    } else {
        // Gérer les erreurs de conversion
        std::cerr << "Erreur lors de la conversion du Markdown en HTML : " << result.description() << std::endl;
        return "";
    }
}

int main() {
    std::string markdown = "Hello **world**! \n\n This is a #header \n\n *Italic* and [link](https://example.com) too!";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise `pugixml` pour créer un document XML à partir du texte Markdown, puis applique des règles de conversion pour transformer le document XML en HTML. Les règles de conversion implémentées ici sont simples et ne couvrent pas toutes les possibilités de Markdown. Il est recommandé de consulter les spécifications de la syntaxe Markdown pour une implémentation plus complète.  L'exemple de code ci-dessus est également destiné à illustrer comment utiliser la fonction. Dans cet exemple, le texte Markdown est "Hello **world**! \n\n This is a #header \n\n *Italic* and [link](https://example.com) too!", et la fonction retourne le texte HTML correspondant. L'HTML généré dans cet exemple est :

